// ─── GROQ OUTPUT PARSER ────────────────────────────────────────────────
// Extracts the JSON object from the Groq agent response.
const agentOutput = $json.output || $json.text || '';
const context     = $('Parse Raw Response').item.json;

let normalized = {};
try {
  // Strip markdown fences if present
  const cleaned = agentOutput
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  normalized = JSON.parse(cleaned);
} catch (e) {
  // Fallback: pass raw context forward with flag
  normalized = {
    brand            : context.brand_expected || 'PARSE_ERROR',
    product_name     : context.raw_name,
    pack_size        : null,
    price_egp        : context.price_egp,
    original_price_egp: context.original_price,
    promo_type       : null,
    discount_percent : null,
    in_stock         : context.in_stock,
    stock_hint       : context.stock_hint,
    platform         : context.platform,
    matched_sku      : 'PARSE_ERROR',
    match_confidence : 'LOW'
  };
}

return {
  ...normalized,
  keyword      : context.keyword,
  our_sku      : context.our_sku,
  is_ours      : context.is_ours,
  category     : context.category,
  scrape_date  : context.scrape_date,
  platform_item_id: context.platform_item_id
};

// ─── OOS DETECTION & ALERT ROUTING ────────────────────────────────────
// Spec Section 6.2 — detects stock transitions and assigns alertType.

const curr = $('Parse Groq Output').item.json;
const prev = $json; // previous row from Price_Log (may be empty first run)

let alertType = null;
let first_seen_oos = prev?.First_Seen_OOS || null;

const prevInStock = prev?.In_Stock === 'TRUE' || prev?.In_Stock === true || prev?.In_Stock === 1;
const currInStock = curr.in_stock === true || curr.in_stock === 'true';

if (prevInStock && !currInStock) {
  // Transition: was in stock → now OOS
  if (curr.is_ours) {
    alertType = 'WARNING_OOS_START';
  } else {
    alertType = 'OPPORTUNITY_COMPETITOR_OOS';
  }
  first_seen_oos = new Date().toISOString();

} else if (!currInStock && curr.is_ours && first_seen_oos) {
  // Still OOS — check if >48h
  const hoursOOS = (Date.now() - new Date(first_seen_oos).getTime()) / 36e5;
  if (hoursOOS > 48) {
    alertType = 'CRITICAL_OOS_PERSISTENT';
  }
}

return {
  ...curr,
  In_Stock        : currInStock,
  First_Seen_OOS  : first_seen_oos,
  alertType       : alertType,
  Price_Index     : null  // calculated in Price Index node
};

// ─── PRICE INDEX CALCULATION ───────────────────────────────────────────
// Spec Section 6.3 — Index = (Competitor_Price / Our_Price) * 100
// Only runs when we have a matched competitor vs. Corona SKU pair.

const curr = $json;

// Skip if unmatched or if this IS our product (we compare against it, not compute index for it)
if (curr.matched_sku === 'UNMATCHED' || curr.matched_sku === 'PARSE_ERROR') {
  return { ...curr, skip_price_index: true };
}

// We'll write a row per product; the actual cross-product index
// is computed in the daily report by joining on SKU across is_ours values.
// Here we emit a Price_Index candidate row.
return {
  ...curr,
  price_index_row: {
    Date            : curr.scrape_date,
    SKU             : curr.matched_sku,
    Platform        : curr.platform,
    Category        : curr.category,
    Is_Ours         : curr.is_ours,
    Price_EGP       : curr.price_egp,
    In_Stock        : curr.In_Stock
  },
  skip_price_index: false
};

